        segments.sort(key=lambda segment: segment[1])
        for idx in range(len(segments) - 1):
            if segments[idx][2] > segments[idx + 1][1]:
                fail(EXIT_INPUT, "INPUT")
        plan[item_id] = segments
    return ("fp", plan)

